 "content": "def transform(grid):
    """Stamp a 3x3 halo of color 1 around each embedded color-2 marker."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            # Markers within the solid 3-fields have at least two orthogonal
            # neighboring field cells; isolated/outside guide marks do not.
            n3 = sum(0 <= r + dr < h and 0 <= c + dc < w and grid[r + dr][c + dc] == 3
                     for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)))
            if n3 >= 2:
                markers.append((r, c))
    for r, c in markers:
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != 2:
                    out[rr][cc] = 1
    return out
